function maxArea(height) {
  // Walls from tallest to shortest.
  const order = height.map((_, i) => i).sort((a, b) => height[b] - height[a]);
  let lo = order[0], hi = order[0];   // leftmost / rightmost of the taller walls
  let best = 0;
  for (let k = 1; k < order.length; k++) {
    const i = order[k];
    // Every wall seen so far is at least as tall, so the level is height[i].
    best = Math.max(best, height[i] * Math.max(i - lo, hi - i));
    lo = Math.min(lo, i);
    hi = Math.max(hi, i);
  }
  return best;
}

class Solution {
    public int maxArea(int[] height) {
        int n = height.length;
        Integer[] order = new Integer[n];   // walls from tallest to shortest
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(height[b], height[a]));
        int lo = order[0], hi = order[0];   // leftmost / rightmost of the taller walls
        int best = 0;
        for (int k = 1; k < n; k++) {
            int i = order[k];
            // Every wall seen so far is at least as tall, so the level is height[i].
            best = Math.max(best, height[i] * Math.max(i - lo, hi - i));
            lo = Math.min(lo, i);
            hi = Math.max(hi, i);
        }
        return best;
    }
}

